use serde::Serialize;use std::{net::UdpSocket,sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},time::{Duration,Instant}};use tauri::{AppHandle,Emitter,Manager,State};const PORT:u16=6454;#[derive(Default)]struct Bridge{running:Mutex<Option<Arc<AtomicBool>>>}#[derive(Clone,Serialize,Default)]struct Stats{datagrams:u64,accepted:u64,rejected:u64,fps:u32,source:String,universe:u16,sequence:u8,last_error:String}#[derive(Clone,Serialize)]struct Frame{universe:u16,data:Vec<u8>}fn parse(buf:&[u8])->Result<(u16,u8,Vec<u8>),String>{if buf.len()<18{return Err("too short".into())}if &buf[0..8]!=b"Art-Net\0"{return Err("bad header".into())}if u16::from_le_bytes([buf[8],buf[9]])!=0x5000{return Err("not ArtDMX".into())}if u16::from_be_bytes([buf[10],buf[11]])<14{return Err("protocol < 14".into())}let len=u16::from_be_bytes([buf[16],buf[17]])as usize;if len<2||len>512||len%2!=0{return Err("invalid DMX length".into())}if buf.len()<18+len{return Err("truncated".into())}let mut data=vec![0u8;512];data[..len].copy_from_slice(&buf[18..18+len]);Ok((u16::from_le_bytes([buf[14],buf[15]])+1,buf[12],data))}#[tauri::command]fn start_listener(app:AppHandle,state:State<Bridge>)->Result<(),String>{let mut g=state.running.lock().map_err(|_|"state lock")?;if g.as_ref().is_some_and(|x|x.load(Ordering::Relaxed)){return Ok(())}let run=Arc::new(AtomicBool::new(true));*g=Some(run.clone());drop(g);std::thread::spawn(move||{let sock=match UdpSocket::bind(("0.0.0.0",PORT)){Ok(s)=>s,Err(e)=>{let _=app.emit("bridge-stats",Stats{last_error:e.to_string(),..Default::default()});return}};let _=sock.set_read_timeout(Some(Duration::from_millis(200)));let mut s=Stats{source:"—".into(),universe:1,..Default::default()};let mut buf=[0u8;530];let mut window=Instant::now();let mut frames=0u32;while run.load(Ordering::Relaxed){match sock.recv_from(&mut buf){Ok((n,src))=>{s.datagrams+=1;s.source=src.to_string();match parse(&buf[..n]){Ok((u,seq,data))=>{s.accepted+=1;s.universe=u;s.sequence=seq;frames+=1;let _=app.emit("dmx-frame",Frame{universe:u,data});},Err(e)=>{s.rejected+=1;s.last_error=e}}let elapsed=window.elapsed();if elapsed>=Duration::from_secs(1){s.fps=(frames as f64/elapsed.as_secs_f64()).round()as u32;frames=0;window=Instant::now()}let _=app.emit("bridge-stats",s.clone());},Err(e)if matches!(e.kind(),std::io::ErrorKind::WouldBlock|std::io::ErrorKind::TimedOut)=>{},Err(e)=>{s.last_error=e.to_string();let _=app.emit("bridge-stats",s.clone());break}}}});Ok(())}#[tauri::command]fn stop_listener(state:State<Bridge>)->Result<(),String>{if let Some(r)=state.running.lock().map_err(|_|"state lock")?.take(){r.store(false,Ordering::Relaxed)}Ok(())}fn packet(universe:u16,channel:u16,value:u8)->Vec<u8>{let mut p=vec![0u8;18+512];p[..8].copy_from_slice(b"Art-Net\0");p[8..10].copy_from_slice(&0x5000u16.to_le_bytes());p[10..12].copy_from_slice(&14u16.to_be_bytes());p[12]=1;p[14..16].copy_from_slice(&(universe.saturating_sub(1)).to_le_bytes());p[16..18].copy_from_slice(&512u16.to_be_bytes());if(1..=512).contains(&channel){p[17+channel as usize]=value}p}#[tauri::command]fn generate_test_frame(universe:u16,channel:u16,value:u8)->Result<(),String>{let sock=UdpSocket::bind(("127.0.0.1",0)).map_err(|e|e.to_string())?;sock.send_to(&packet(universe,channel,value),("127.0.0.1",PORT)).map_err(|e|e.to_string())?;Ok(())}pub fn run(){tauri::Builder::default().manage(Bridge::default()).invoke_handler(tauri::generate_handler![start_listener,stop_listener,generate_test_frame]).run(tauri::generate_context!()).expect("VizBridge failed")}